SOURCES = ["https://vapi.ai/pricing","https://docs.vapi.ai/assistants/model-intelligence/understanding-cost","https://docs.vapi.ai/tools","https://docs.vapi.ai/tools/transfer-call","https://www.retellai.com/pricing","https://docs.retellai.com/deploy/chat-widget","https://elevenlabs.io/docs/reception-ai/billing/plans-and-pricing","https://elevenlabs.io/docs/reception-ai/scheduling/overview","https://elevenlabs.io/docs/reception-ai/integrations/overview","https://elevenlabs.io/docs/reception-ai/quickstart","https://elevenlabs.io/pricing/agents","https://elevenlabs.io/docs/help-center/product/eleven-agents/how-do-i-use-tools-with-eleven-agents","https://developers.openai.com/api/docs/pricing","https://developers.openai.com/api/docs/guides/voice-sip","https://developers.openai.com/api/docs/guides/voice-agents","https://www.twilio.com/en-us/voice/pricing/de","https://www.edpb.europa.eu/sme/find-practical-info/faq_ro"]
FAQS = [["What is an AI receptionist?","An AI receptionist is a voice-enabled phone answering system that identifies itself, handles permitted customer questions, checks live booking availability, books appointments through an authorized calendar integration, and transfers calls when needed. It must not invent bookings or act beyond granted permissions."],["How much does an AI receptionist cost per month?","Costs depend on call minutes, subscription tier, model, voice, telephone carrier, retries and add-ons. Vapi lists $0.05 per minute hosting plus usage costs; Retell advertises $0.07–$0.31 per minute; ElevenLabs Reception lists paid plans from $29/month with included credits. A self-built OpenAI Realtime application has token-based model charges plus phone and backend costs."],["Which is the best AI receptionist for small business?","There is no provider-independent winner. ElevenLabs Reception offers an integrated ready-made scheduling product; Vapi and Retell are configurable phone-agent platforms; OpenAI Realtime is an API toolkit for teams willing to build telephony, scheduling and operational controls. Choose based on your required integrations, test completion rates and total monthly spend."],["Can an AI receptionist book appointments in Google Calendar?","Yes, when it has a properly configured scheduling integration. ElevenLabs Reception documents Google Calendar availability syncing; Vapi offers callable calendar tools. A custom system must check free/busy and commit the event through authorized server APIs before confirming to the caller."],["Can an AI receptionist transfer calls to a person?","Yes, with a telephony integration and an authorized transfer tool. Vapi has a transfer-call tool, ElevenAgents supports system transfers, and OpenAI Realtime SIP documents a refer-call endpoint. Verify that your provider, phone number, destination and call flow support the feature."],["Do AI receptionists work with existing phone numbers?","Often through call forwarding, SIP trunking or a compatible carrier such as Twilio, but number portability and regional availability depend on the vendor and phone carrier. Test inbound routing, transfers and fallback before porting a business-critical number."],["Is an AI receptionist the same as an AI chatbot?","No. A phone AI receptionist must manage live call audio, turn-taking, interruption, telephone routing, identity and booking side effects. A web chatbot can share the language model and knowledge base without using telephony."],["What is the difference between Vapi and Retell AI?","Both are configurable voice-agent platforms. Vapi separates hosting from transcriber, language-model, voice and phone-provider charges and documents reusable tools. Retell publishes a composed per-minute voice agent range and detailed voice, model, telephony and add-on components. Compare using the same call scenario rather than treating headline prices as identical units."],["Is ElevenLabs Reception the same as ElevenAgents?","No. Reception is a packaged business receptionist with plans, phone minutes, staff calendars and booking tools. ElevenAgents is a developer-focused agent platform with its own included minutes, LLM costs and telephony pricing. Do not combine their plan prices in one quote."],["Does OpenAI Realtime charge a flat price per call?","No. GPT-Realtime-2.1 uses modality-specific audio and text token prices. The separate GPT-Live 1 product has a per-second session price plus backend/tool usage. A telephone provider and application backend add other costs."],["Can an AI receptionist handle medical or legal calls?","It can route or schedule calls with suitable controls, but sensitive data, regulated advice and emergency scenarios require sector-specific assessment, privacy protections, explicit human escalation and provider agreements; no platform listing alone establishes legal compliance."],["Do I have to tell callers they are speaking to AI or being recorded?","Plan to disclose that the assistant is automated and explain recording and privacy practices. Recording consent, lawful basis, notices, storage and retention rules vary by jurisdiction. The European Data Protection Board requires appropriate information to callers where their calls are recorded; local legal review is needed."],["How do I prevent double-booked appointments?","Read real-time calendar availability, enforce service duration and time zones, use an idempotency key, perform an authoritative availability check during the final write, and only announce confirmed bookings after the calendar API succeeds."],["How should I test an AI receptionist before launching?","Use controlled calls covering accents, names, noisy lines, wrong dates, unavailable slots, transfers, repeated webhooks, consent, refusals and emergency handoff. Measure task completion, confirmed booking rate, false confirmations, transfer success, p95 latency, and cost per successful outcome."],["Can AI receptionist software replace a human receptionist?","It can automate routine information and booking tasks, but should hand off emergencies, unusual cases, accessibility needs and uncertain identity or authorization. The amount of human work reduced depends on the business and tested task outcomes."]]
BODY_HTML = "\n<section class=\"shell receptionist-guide\" data-ai-receptionist-guide aria-labelledby=\"receptionist-guide-title\">\n<div class=\"arg-intro\">\n<p class=\"eyebrow\">SXF PRACTICAL GUIDE / SMALL BUSINESS / VOICE AI</p>\n<h2 id=\"receptionist-guide-title\">An AI receptionist should answer the phone—and finish the task reliably.</h2>\n<p>Looking for an <strong>AI receptionist</strong>, <strong>AI phone answering service</strong>, or a way to <strong>build an AI voice agent</strong> for your business? The useful decision is not which demo voice sounds most human. It is whether a real caller can reach the right person, make a genuine booking, receive a correct answer and understand when automation has reached its limits. This guide compares <strong>Vapi, Retell AI, ElevenLabs Reception / ElevenAgents and OpenAI Realtime</strong> using primary-source documentation and separate billing units.</p>\n<blockquote class=\"arg-answer\"><strong>Direct answer:</strong> For an off-the-shelf business receptionist with native calendar scheduling, evaluate ElevenLabs Reception. For configurable AI telephone workflows, evaluate Vapi or Retell. For a fully custom speech-to-speech backend, use OpenAI Realtime with your own SIP/telephony, security and calendar integration. None is proven universally best: test successful appointments, transfer reliability, privacy, and cost per completed call.</blockquote>\n<nav class=\"arg-toc\" aria-label=\"On this page\"><a href=\"#arg-definition\">How it works</a><a href=\"#arg-platforms\">Platform comparison</a><a href=\"#arg-pricing\">Real costs</a><a href=\"#arg-calculator\">Cost calculator</a><a href=\"#arg-build\">Build steps</a><a href=\"#arg-scripts\">Call script</a><a href=\"#arg-security\">Privacy</a><a href=\"#arg-evaluation\">Tests</a><a href=\"#arg-faq\">FAQ</a></nav>\n<p class=\"arg-disclosure\">Editorial research verified October 31, 2026. Price tables are a dated snapshot of publicly displayed list prices, not quotes. We did not secretly place phone calls or benchmark any provider for this article; the original SXF calculator and 20-call evaluation plan are explicit examples, not measurements.</p>\n</div>\n<section class=\"arg-section\" id=\"arg-definition\"><p class=\"eyebrow\">WHAT IT DOES</p><h2>What is an AI receptionist and how does it work?</h2>\n<p>An <strong>AI receptionist</strong> is a software system that answers incoming phone calls using speech recognition or realtime audio models, interprets the request, and invokes approved business tools. It can explain hours, route to the right department, check a staff calendar, create a booking, send a confirmation and hand the call to a human. A basic prerecorded IVR asks the caller to press buttons; a conversational voice agent can understand open-ended speech and follow up when details are unclear.</p>\n<figure class=\"arg-figure\"><img src=\"/guides/ai-receptionist/images/ai-receptionist-architecture.svg\" alt=\"Architecture: caller and phone carrier connect to a voice agent, which verifies identity, queries scheduling or CRM, commits only authorized appointments and transfers to staff when needed.\" loading=\"lazy\" width=\"1200\" height=\"620\"/><figcaption>Original SXF architecture: spoken intent must pass application authorization and verified tool results before the agent confirms an action.</figcaption></figure>\n<div class=\"arg-grid\"><article><span>01 / CONNECT</span><h3>Phone number and media</h3><p>A carrier or SIP trunk routes an inbound PSTN call to the agent platform. A browser microphone session is not automatically a real inbound business number; configure actual telephony separately.</p></article><article><span>02 / UNDERSTAND</span><h3>Speech and conversation</h3><p>A pipeline may combine speech-to-text, an LLM, and text-to-speech; native speech-to-speech models combine more of this interaction. Both require interruption handling and real-time monitoring.</p></article><article><span>03 / ACT</span><h3>Calendar, CRM and transfer</h3><p>Behind the conversation, a server checks availability, caller consent, permissions, booking constraints, and transfer destinations. A model-generated sentence is never proof a database write succeeded.</p></article><article><span>04 / REVIEW</span><h3>Audit and human handoff</h3><p>When the tool fails or the user needs sensitive assistance, transfer to a staffed line or take a message. Retain only the call information justified by your privacy policy.</p></article></div>\n<p><strong>AI receptionist vs voice chatbot:</strong> both may share speech and language models, but telephony introduces call routing, inbound numbers, transfers, missed calls, busy lines and jurisdiction-specific rules. The business system—not the model—ultimately owns the appointment.</p></section>\n<section class=\"arg-section\" id=\"arg-platforms\"><p class=\"eyebrow\">BEST AI RECEPTIONIST SOFTWARE / BUYER SHORTLIST</p><h2>Vapi vs Retell AI vs ElevenLabs vs OpenAI Realtime.</h2>\n<p>These are not perfectly interchangeable products. ElevenLabs sells a packaged <strong>Reception</strong> product as well as a separate <strong>ElevenAgents</strong> platform. OpenAI sells realtime models and tools rather than an end-to-end phone answering subscription. The right comparison starts with how much infrastructure you want to own.</p>\n<div class=\"arg-scroll\"><table class=\"arg-table\"><caption>Provider-documented AI receptionist options checked October 31, 2026</caption><thead><tr><th>Platform</th><th>Typical starting point</th><th>Calendar / CRM path</th><th>Call transfer</th><th>Price basis</th></tr></thead><tbody>\n<tr><th>Vapi</th><td>Customizable voice assistant with models, voice and telephony components</td><td>Tools, Google Calendar, APIs and webhooks</td><td>Documented transfer-call tool</td><td>Hosting per minute + model, speech and carrier usage</td></tr>\n<tr><th>Retell AI</th><td>Configurable AI phone agent with dashboard, testing and integrations</td><td>Configure custom functions and connected business workflows</td><td>Verify transfer behavior in chosen agent/telephony setup</td><td>Published aggregate voice-agent range; add-ons and telephony can apply</td></tr>\n<tr><th>ElevenLabs Reception</th><td>Ready-made AI receptionist for calls, services, staff and scheduling</td><td>Built-in booking, Google Calendar, Calendly, Cal.com, HubSpot and webhooks</td><td>Business rules and routing; verify local number support</td><td>Monthly plan with bundled phone-minute credits and overages</td></tr>\n<tr><th>ElevenAgents</th><td>Developer voice/chat agent toolkit</td><td>Webhooks and client/system tools to your backend</td><td>System transfer tool</td><td>Included minutes + overage; LLM and phone provider separately</td></tr>\n<tr><th>OpenAI Realtime</th><td>Build-your-own realtime conversational backend</td><td>You implement calendar/CRM function tools and server-side checks</td><td>Documented SIP refer endpoint</td><td>Audio/text tokens + telephony and backend overhead</td></tr></tbody></table></div>\n<div class=\"arg-grid\"><article><span>BUILDER PLATFORM</span><h3>Vapi</h3><p>Offers a $0.05/min usage-only hosting fee, $5 initial credits, optional service packages, and model/transcriber/voice costs passed through. It documents calendar and transfer tools. <a href=\"https://vapi.ai/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">Official pricing</a> · <a href=\"https://docs.vapi.ai/tools\" target=\"_blank\" rel=\"noopener noreferrer\">tools documentation</a>.</p></article><article><span>BUILDER PLATFORM</span><h3>Retell AI</h3><p>Publishes an approximate $0.07–$0.31 per minute pay-as-you-go voice-agent range. Its example $0.15/min composition is not the price of every configuration; telephony, voice, model and add-ons change the result. <a href=\"https://www.retellai.com/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">Official calculator</a>.</p></article><article><span>READY-MADE BUSINESS PRODUCT</span><h3>ElevenLabs Reception</h3><p>Business-specific scheduling, staff/asset constraints and calendar sync are included. The published monthly tiers are separate from ElevenAgents developer subscriptions. Supported automatic number provisioning differs by country. <a href=\"https://elevenlabs.io/reception\" target=\"_blank\" rel=\"noopener noreferrer\">Reception</a> · <a href=\"https://elevenlabs.io/docs/reception-ai/quickstart\" target=\"_blank\" rel=\"noopener noreferrer\">setup guide</a>.</p></article><article><span>DEVELOPER PLATFORM</span><h3>ElevenAgents</h3><p>Lets developers choose a voice agent stack with webhook tools, transfers, and configurable models; the plan includes call minutes, while LLM and telephony usage can be extra. Avoid mistakenly attributing Reception booking features to every ElevenAgents agent. <a href=\"https://elevenlabs.io/pricing/agents\" target=\"_blank\" rel=\"noopener noreferrer\">ElevenAgents prices</a>.</p></article><article><span>CUSTOM API / SIP</span><h3>OpenAI Realtime</h3><p>Use a phone provider/SIP trunk and your own application backend with GPT-Realtime-2.1. OpenAI describes incoming-call webhooks, sideband events and call transfers. Its model is metered by modality tokens, not a flat receptionist subscription. <a href=\"https://developers.openai.com/api/docs/guides/voice-sip\" target=\"_blank\" rel=\"noopener noreferrer\">Telephony/SIP guide</a>.</p></article></div>\n<p class=\"arg-note\">“Best” is defined by the required outcome, not a paid partner or an unverified benchmark. No vendor supplied a measured SXF ranking for this page. Price/feature availability may vary by region and configuration.</p></section>\n<section class=\"arg-section\" id=\"arg-pricing\"><p class=\"eyebrow\">AI RECEPTIONIST PRICING 2026 / REAL UNITS</p><h2>How much does an AI receptionist cost per minute and per month?</h2><p>A credible AI phone answering cost estimate starts with <strong>connected minutes</strong>, then adds any phone carrier, speech-to-text, language model, text-to-speech, integrations, number rental, taxes and support package. Different vendors bundle different pieces. One per-minute line item must not be compared with a complete phone bill as if both include the same services.</p>\n<div class=\"arg-scroll\"><table class=\"arg-table\"><caption>Selected official public pricing snapshot, October 31, 2026 (USD)</caption><thead><tr><th>Platform</th><th>Published starting unit</th><th>Not necessarily included</th><th>Evidence</th></tr></thead><tbody>\n<tr><th>Vapi usage-only</th><td><strong>$0.05 / connected minute</strong> hosting</td><td>STT, LLM, TTS, phone/transport and optional packages</td><td><a href=\"https://vapi.ai/pricing\">Vapi</a></td></tr>\n<tr><th>Retell AI pay-as-you-go</th><td><strong>$0.07–$0.31 / voice minute</strong> advertised range</td><td>Selected voice/model/add-ons; carrier rates depend on setup</td><td><a href=\"https://www.retellai.com/pricing\">Retell</a></td></tr>\n<tr><th>ElevenLabs Reception</th><td><strong>$29 / $79 / $199 month</strong> Basic / Plus / Premium</td><td>Overages above bundled 75 / 275 / 1,000 credits</td><td><a href=\"https://elevenlabs.io/docs/reception-ai/billing/plans-and-pricing\">Reception plans</a></td></tr>\n<tr><th>ElevenAgents developer plan</th><td><strong>$6 / month Starter</strong> with 75 included call minutes; additional $0.08/min</td><td>Model usage and telephony charged separately</td><td><a href=\"https://elevenlabs.io/pricing/agents\">Agents pricing</a></td></tr>\n<tr><th>OpenAI GPT-Realtime-2.1</th><td><strong>$32 input / $64 output</strong> per 1M audio tokens</td><td>Text tokens, cache effects, phone carrier and application infrastructure</td><td><a href=\"https://developers.openai.com/api/docs/pricing\">OpenAI</a></td></tr>\n</tbody></table></div>\n<p><strong>Why billing may surprise you:</strong> Vapi's published pricing calculator adds hosting, voice, model and transcriber separately. Retell's displayed estimate of $0.150/min is one selected configuration. ElevenLabs Reception's monthly allowance is a credit pool: its official plans page lists 1 credit per phone minute, with Basic/Plus/Premium overages listed at $0.45/$0.38/$0.30 per credit. Another official usage page presents different example overage values; verify the live checkout and invoice rather than silently selecting a conflicting rate.</p>\n<p><strong>OpenAI API is not GPT-Live:</strong> The GPT-Realtime-2.1 voice model uses token-based audio ($32 input and $64 output per million) and text billing ($4 input / $24 output per million text tokens). The separate GPT-Live-1 product has a $0.05/min session charge, with backend model and tool usage billed on top. Do not substitute the Live session rate for Realtime token prices. See SXF's <a href=\"/models/gpt-realtime-2-1/\">GPT-Realtime-2.1 API pricing breakdown</a>.</p>\n<p><strong>Telephony varies by country:</strong> Twilio publishes separate inbound/outbound rates by location; its Germany page, for example, lists inbound local calls at $0.0100/min in an August 2026 price snapshot. That is not a global number or a complete AI-agent price. <a href=\"https://www.twilio.com/en-us/voice/pricing/de\" target=\"_blank\" rel=\"noopener noreferrer\">Official regional carrier example</a>.</p>\n</section>\n<section class=\"arg-section\" id=\"arg-calculator\"><p class=\"eyebrow\">ORIGINAL SXF COST TOOL</p><h2>AI receptionist cost calculator: estimate your monthly answering bill.</h2>\n<p>This original, browser-only <strong>SXF scenario calculator</strong> is not a vendor quote. It uses the selected assumptions described under the result; change all inputs to reflect your call logs and vendor price. For OpenAI Realtime, supply actual or estimated modality-token consumption rather than pretending there is a fixed API price per minute.</p>\n<div class=\"arg-calc\" data-receptionist-calculator>\n<div class=\"arg-controls\">\n<label>Monthly calls <input type=\"number\" data-field=\"calls\" min=\"0\" max=\"1000000\" step=\"1\" value=\"300\"/></label>\n<label>Average call length, minutes <input type=\"number\" data-field=\"minutes\" min=\"0\" max=\"240\" step=\"0.5\" value=\"3\"/></label>\n<label>Provider scenario <select data-field=\"platform\"><option value=\"vapi\">Vapi: component estimate</option><option value=\"retell\">Retell: published $0.15/min example</option><option value=\"reception\">ElevenLabs Reception Plus</option><option value=\"agents\">ElevenAgents Starter + external costs</option><option value=\"openai\">OpenAI GPT-Realtime-2.1 token example</option></select></label>\n<label>Phone / telecom cost, $/minute <input type=\"number\" data-field=\"carrier\" min=\"0\" max=\"5\" step=\"0.005\" value=\"0.01\"/></label>\n<label>Successful task rate, % <input type=\"number\" data-field=\"success\" min=\"1\" max=\"100\" step=\"1\" value=\"80\"/></label>\n</div><div class=\"arg-calc-results\" aria-live=\"polite\"><div><span>Estimated connected minutes</span><strong data-out=\"totalMinutes\">900</strong></div><div><span>Illustrative monthly cost</span><strong data-out=\"monthly\">$0.00</strong></div><div><span>Cost / connected call</span><strong data-out=\"call\">$0.00</strong></div><div><span>Cost / successful call</span><strong data-out=\"success\">$0.00</strong></div></div>\n<p class=\"arg-assumption\" data-out=\"assumption\">Estimates update when you change the inputs.</p>\n<details><summary>Advanced assumptions: override component costs</summary><div class=\"arg-controls\">\n<label>Vapi model, voice and transcriber, $/min <input type=\"number\" data-field=\"vapiParts\" min=\"0\" max=\"5\" step=\"0.005\" value=\"0.055\"/></label>\n<label>Retell voice agent scenario, $/min <input type=\"number\" data-field=\"retellRate\" min=\"0\" max=\"5\" step=\"0.005\" value=\"0.15\"/></label>\n<label>ElevenAgents LLM estimate, $/min <input type=\"number\" data-field=\"agentsLLM\" min=\"0\" max=\"5\" step=\"0.005\" value=\"0.025\"/></label>\n<label>OpenAI uncached audio input tokens / call <input type=\"number\" data-field=\"audioIn\" min=\"0\" max=\"1000000\" step=\"100\" value=\"4500\"/></label>\n<label>OpenAI audio output tokens / call <input type=\"number\" data-field=\"audioOut\" min=\"0\" max=\"1000000\" step=\"100\" value=\"6000\"/></label>\n<label>OpenAI text input tokens / call <input type=\"number\" data-field=\"textIn\" min=\"0\" max=\"1000000\" step=\"100\" value=\"900\"/></label>\n<label>OpenAI text output tokens / call <input type=\"number\" data-field=\"textOut\" min=\"0\" max=\"1000000\" step=\"100\" value=\"500\"/></label></div></details>\n<p><strong>Formula:</strong> total connected minutes = calls × average duration; scenario cost = platform charges + assumed carrier charges; cost per successful call = monthly scenario cost ÷ (calls × task-success fraction). “Successful” is not a provider promise. A transferred but unresolved call should not be counted as an accomplished booking unless your business explicitly defines it that way.</p>\n</div></section>\n<section class=\"arg-section\" id=\"arg-build\"><p class=\"eyebrow\">IMPLEMENTATION WALKTHROUGH</p><h2>How to build an AI receptionist that answers calls and books appointments.</h2>\n<ol class=\"arg-checklist\"><li><strong>Define the allowed jobs.</strong> List office hours, locations, supported services, booking durations and transfer reasons. Explicitly block medical diagnosis, legal advice, payment-card capture and other tasks the business has not authorized.</li>\n<li><strong>Choose a real phone route.</strong> Assign a number or forward an existing number to your platform. Document geographic support, call concurrency, voicemail, business-hours routing and a fallback number. Test call forwarding and caller ID before migrating primary lines.</li>\n<li><strong>Set up the verified knowledge base.</strong> Import only current opening hours, addresses, service descriptions, prices and cancellation rules. Store source URL or owner for each fact. If information is uncertain, ask the caller to wait for a human confirmation instead of guessing.</li>\n<li><strong>Connect a scheduling backend.</strong> Link a staff calendar and business rules. Read actual free/busy state, including staff time off and required equipment. In a custom integration, use service-account or OAuth credentials in the server—not in prompts or browser code.</li>\n<li><strong>Implement tools with restricted scope.</strong> Use server-side functions such as <code>check_availability</code>, <code>create_booking</code>, <code>cancel_booking</code>, <code>route_call</code> and <code>send_confirmation</code>. A tool takes structured, validated parameters and returns a factual success or failure. Never treat tool-call text as a completed write.</li>\n<li><strong>Confirm before side effects.</strong> Have the caller repeat name, date, timezone, service and contact information. Re-query availability immediately before writing; use idempotency keys to stop duplicate appointments when a webhook retries.</li>\n<li><strong>Handle interruptions and transfers.</strong> Configure voice activity detection and barge-in, a staffed fallback route and a timeout. If the human destination is unavailable, take a message with consent rather than trapping the caller in a repeating loop.</li>\n<li><strong>Deploy privacy controls.</strong> State the AI disclosure and recording policy early. Minimize storage, document retention, enable redaction where needed, test data deletion, limit who may listen to recordings, and review vendor contracts.</li>\n<li><strong>Simulate real calls.</strong> Use the twenty scenarios below before sending public traffic. Review booking confirmations and failure logs with staff; only then move to a staged launch with monitoring.</li>\n</ol>\n<h3>Appointment-booking tool contract (implementation-neutral example)</h3><pre class=\"arg-code\"><code>{\n  \"name\": \"create_booking\",\n  \"arguments\": {\n    \"service_id\": \"consultation_30m\",\n    \"start_at\": \"2026-11-05T13:00:00+01:00\",\n    \"caller_confirmation\": true,\n    \"idempotency_key\": \"call_abc123_booking_1\"\n  },\n  \"server_checks\": [\n    \"authenticated_business\",\n    \"approved_service\",\n    \"timezone_valid\",\n    \"staff_free\",\n    \"slot_not_reserved\",\n    \"caller_confirmed\"\n  ],\n  \"success_response\": {\n    \"status\": \"confirmed\",\n    \"booking_id\": \"bk_456\"\n  }\n}</code></pre>\n<p>This is <strong>a conceptual tool contract, not code to paste into Vapi, Retell or OpenAI</strong>. Field names differ by vendor. When the calendar API times out, respond “I cannot confirm the appointment yet” and retry safely server-side, rather than inventing a confirmation number.</p>\n<p>ElevenLabs Reception already implements staff/service calendars, and its Google Calendar integration checks busy times. Vapi documents reusable calendar and transfer tools. When using OpenAI Realtime directly, the telephony SIP documentation covers an inbound webhook, sideband session and <code>refer</code> transfer, but your own application still implements the booking backend. <a href=\"https://elevenlabs.io/docs/reception-ai/scheduling/overview\" target=\"_blank\" rel=\"noopener noreferrer\">Reception scheduling</a> · <a href=\"https://docs.vapi.ai/tools\" target=\"_blank\" rel=\"noopener noreferrer\">Vapi tools</a> · <a href=\"https://developers.openai.com/api/docs/guides/voice-sip\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI SIP</a>.</p>\n</section>\n<section class=\"arg-section\" id=\"arg-scripts\"><p class=\"eyebrow\">COPY-READY DESIGN BLUEPRINT</p><h2>AI receptionist conversation script: greeting, booking, transfer and refusal.</h2>\n<p>The following <strong>original SXF example</strong> is a starting point for your own policy and agent prompt, not vendor-specific system prompt syntax. It separates speaking politely from taking authorized action.</p>\n<div class=\"arg-script\"><p><strong>Greeting:</strong> “Hello, you’ve reached Example Clinic’s automated receptionist. I can help with office hours, scheduling or connecting you with staff. This call may be processed by our service providers. Would you like to book an appointment or speak to a person?”</p><p><strong>Booking:</strong> “Which service and day would you prefer? I’ll check live availability. I have Thursday at 2:00 p.m. in Berlin time available. Shall I book that slot for you?” Only say “confirmed” after a successful calendar response.</p><p><strong>Clarify a name or number:</strong> “Could you spell your last name? I’ll repeat it back before I save anything.” If ambiguity remains, send a secure follow-up or transfer rather than copying a guessed name to CRM.</p><p><strong>Human transfer:</strong> “I can connect you with our staff now. May I share a short summary of this request so you don’t need to repeat it?” Apply the consent rule before transmitting personal details.</p><p><strong>Uncertain answer:</strong> “I don’t have a verified answer to that question. I can take a message or connect you with our team.” Do not invent prices, eligibility or clinical instructions.</p><p><strong>Emergency:</strong> “I can’t provide emergency assistance. If you may be in immediate danger, contact your local emergency services now.” The business should test country-specific escalation language and pathways.</p></div>\n<h3>Three checks that prevent expensive mistakes</h3><div class=\"arg-grid\"><article><span>NO FALSE BOOKINGS</span><h3>Only state what the API confirmed</h3><p>The calendar write result, not the agent's intention, is the source of truth. Use a distinct booking confirmation identifier and a recorded action status.</p></article><article><span>NO HIDDEN TRANSFER</span><h3>Plan a person in the loop</h3><p>Give callers an understandable exit. Ensure transfer destinations, hours and fallback answer rules are current; verify completed transfers, not just requests to transfer.</p></article><article><span>NO SECRET CAPTURE</span><h3>Limit data collection</h3><p>Ask only for fields needed to perform the stated task. Avoid collecting payment card numbers and unrelated medical data over unrestricted transcripts.</p></article></div>\n</section>\n<section class=\"arg-section\" id=\"arg-security\"><p class=\"eyebrow\">SECURITY, COMPLIANCE AND TRUST</p><h2>Is an AI receptionist legal and safe for business calls?</h2><p>Using a voice agent does not remove privacy or telemarketing obligations. Requirements vary with the caller's country, where the business operates, whether calls are recorded, the service category and the data involved. Plan the disclosure, lawful basis, retention, processors, transfer agreements, and caller-access workflows before launch. This guide is technical orientation, not legal advice.</p>\n<div class=\"arg-grid\"><article><span>TRANSPARENCY</span><h3>Tell callers what is automated</h3><p>Use a clear automated-receptionist greeting. If recording/transcription occurs, explain relevant purposes and privacy information before processing; determine whether and how consent or objection rights apply under local law.</p></article><article><span>CONTROL</span><h3>Enforce least privilege</h3><p>Caller instructions are untrusted. Never let an utterance change tool authorization, read another customer's bookings or trigger an unapproved outbound action. Bind calendar permissions to the verified business.</p></article><article><span>RETENTION</span><h3>Protect phone recordings</h3><p>Limit transcripts, call audio and CRM notes to the legitimate purpose. Provide deletion or access mechanisms and configure vendor retention and region settings where applicable.</p></article><article><span>RELIABILITY</span><h3>Escalate sensitive incidents</h3><p>For healthcare, legal or financial workflows, require domain-specific risk review, appropriate vendor agreements and clear human takeover. Telephony and cloud certifications alone do not guarantee compliance for your use case.</p></article></div>\n<p>The European Data Protection Board's small-business FAQ states that clients whose calls are recorded need information about the recording purposes, recipients and relevant access/objection rights. Some jurisdictions require one-party or all-party recording consent; local legal counsel should confirm the details. <a href=\"https://www.edpb.europa.eu/sme/find-practical-info/faq_ro\" target=\"_blank\" rel=\"noopener noreferrer\">EDPB official guidance</a>.</p>\n<p>For broader technical controls, see <a href=\"/guides/ai-agent-security/\">SXF's AI agent security guide</a>, <a href=\"/guides/ai-agent-authorization/\">authorization and delegated permissions</a>, and <a href=\"/guides/ai-agent-observability/\">production agent observability</a>.</p></section>\n<section class=\"arg-section\" id=\"arg-evaluation\"><p class=\"eyebrow\">ORIGINAL SXF ACCEPTANCE TEST PLAN</p><h2>How to test an AI phone receptionist before customers call.</h2><p>This is an <strong>editorial evaluation design</strong>, not a report of live provider testing. Use twenty scripted calls, record all failures and report the exact model, region, telephony route and configuration. Run calls across at least two acoustic conditions and more than one accent if those are present in your audience.</p>\n<div class=\"arg-scroll\"><table class=\"arg-table\"><caption>20-call acceptance matrix: five cases across four dimensions</caption><thead><tr><th>Dimension</th><th>Five concrete tests</th><th>Failure signal</th></tr></thead><tbody><tr><th>Booking (5)</th><td>Available slot; occupied slot; timezone conflict; repeated webhook; calendar outage</td><td>False confirmation, duplicate appointment or wrong hour</td></tr><tr><th>Understanding (5)</th><td>Spelled surname; ambiguous date; loud background; interrupted speech; bilingual caller</td><td>Uncorrected contact data or repeated misunderstanding</td></tr><tr><th>Routing (5)</th><td>Request human; staff busy; after-hours call; wrong department; disconnect mid-transfer</td><td>Lost caller, misleading transfer status or no safe fallback</td></tr><tr><th>Trust and security (5)</th><td>Recording disclosure; request for another user's data; prompt injection; emergency language; deletion request</td><td>Secret recording, sensitive data leak or unauthorized side effect</td></tr></tbody></table></div>\n<p>Measure <strong>confirmed booking rate</strong> = valid server-confirmed bookings ÷ booking requests, <strong>transfer completion rate</strong> = connected staff transfers ÷ requested transfers, <strong>false-confirmation count</strong>, <strong>p95 response latency</strong>, <strong>cost per resolved caller request</strong>, and <strong>human takeover burden</strong>. Choose acceptance thresholds based on business harm, not an impressive synthetic percentage.</p>\n<p><strong>Recommended staged rollout:</strong> first use sandbox calendars, then a temporary test number, then limited business hours with staff supervision, and only later production routing. Never port a primary company phone number before a documented rollback path and an after-hours test.</p></section>\n<section class=\"arg-section\" id=\"arg-faq\"><p class=\"eyebrow\">FREQUENT SEARCH QUESTIONS</p><h2>AI receptionist FAQ: cost, bookings, transfers, phones and privacy.</h2>\n<div class=\"arg-faq\">\n<details><summary>How much is an AI receptionist per month?</summary><p>It depends on calls, plan and integrations. Vapi has a $0.05/min platform fee plus component costs; Retell advertises $0.07–$0.31/min; ElevenLabs Reception plans start at $29/month and have bundled credits; a custom OpenAI Realtime stack is billed by audio/text tokens plus telephony.</p></details>\n<details><summary>Which AI receptionist is best for a small business?</summary><p>For ready-made appointment scheduling, evaluate ElevenLabs Reception. For developer-controlled calls, compare Vapi and Retell. For full custom control, build on OpenAI Realtime. Measure real completion, costs, privacy and support rather than relying on generic rankings.</p></details>\n<details><summary>Can it book appointments on Google Calendar?</summary><p>Yes, with an authorized integration. Check free/busy and business rules, then persist the event; only confirm after the calendar write succeeds. ElevenLabs Reception documents live availability integration and Vapi offers calendar tools.</p></details>\n<details><summary>Can I keep my existing business phone number?</summary><p>Depending on the carrier and region, many setups use forwarding or SIP. Confirm number availability, porting requirements, international calling, business-hours routing and transfer before migrating.</p></details>\n<details><summary>Can an AI receptionist transfer a call to a human?</summary><p>Yes, with compatible phone routing and an enabled transfer tool. Test successful connection and the fallback when the destination is unavailable.</p></details>\n<details><summary>Is an AI receptionist just a chatbot?</summary><p>No. It manages live telephone audio, interruptions, transfers, calendar writes and phone-provider constraints that a text chatbot alone does not handle.</p></details>\n<details><summary>Does OpenAI Realtime cost $0.05 per minute?</summary><p>No. GPT-Realtime-2.1 is billed by modality-specific tokens. The distinct GPT-Live-1 service has a $0.05/min session rate plus separate backend costs; don't mix their pricing.</p></details>\n<details><summary>Are ElevenLabs Reception and ElevenAgents identical?</summary><p>No. Reception is a packaged business phone answering and booking service. ElevenAgents is the developer platform with separate call-minute and model/telephony billing.</p></details>\n<details><summary>Can it replace my reception team?</summary><p>It may handle routine work, but unusual, vulnerable or sensitive callers need accessible human support. Quantify valid bookings, missed calls and customer satisfaction before deciding staffing changes.</p></details>\n<details><summary>What about recording and GDPR?</summary><p>Provide appropriate information, assess lawful basis and jurisdiction-specific consent rules, minimize retention, restrict access and honor applicable data subject rights. Have a privacy professional review the call flow.</p></details>\n<details><summary>How do I prevent double bookings?</summary><p>Read availability, validate service duration and timezone, recheck on write, use idempotency keys and announce a booking only after the API returns a real confirmation.</p></details>\n<details><summary>What should I test before going live?</summary><p>Run appointment, accent/noise, transfer, prompt-injection, privacy and error-recovery cases. Track actual success rates, false confirmations, human handoffs and cost per resolved task.</p></details>\n</div></section>\n<section class=\"arg-section\"><p class=\"eyebrow\">PRIMARY SOURCE LEDGER / METHODOLOGY</p><h2>References checked for this AI receptionist buying guide.</h2><p>Verified October 31, 2026 using official vendor pricing, API and integration guides and European regulator guidance. Prices are examples from published list-rate pages. Each provider has different included services and contractual limits; there is no fabricated independent product benchmark or promise of search rank. Feature and pricing claims should be updated as vendor documents change.</p><div class=\"arg-sources\"><a href=\"https://vapi.ai/pricing\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Vapi official pricing</strong><span>$0.05/min hosting, models, transcriber, voice and telephony ↗</span></a><a href=\"https://docs.vapi.ai/assistants/model-intelligence/understanding-cost\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Vapi costs explained</strong><span>Why estimates and actual usage can differ ↗</span></a><a href=\"https://docs.vapi.ai/tools\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Vapi Tools</strong><span>Calendar, webhooks and protected tool calls ↗</span></a><a href=\"https://docs.vapi.ai/tools/transfer-call\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Vapi transfer a call</strong><span>Warm and cold call routing / SIP options ↗</span></a><a href=\"https://www.retellai.com/pricing\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Retell AI pricing</strong><span>$0.07–$0.31/min advertised voice agent range ↗</span></a><a href=\"https://docs.retellai.com/deploy/chat-widget\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Retell web / voice widget</strong><span>Browser voice and phone callback architecture ↗</span></a><a href=\"https://elevenlabs.io/docs/reception-ai/billing/plans-and-pricing\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenLabs Reception plans</strong><span>Subscription bundles, minutes and overage ↗</span></a><a href=\"https://elevenlabs.io/docs/reception-ai/scheduling/overview\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenLabs Reception scheduling</strong><span>Staff, services, assets and booking constraints ↗</span></a><a href=\"https://elevenlabs.io/docs/reception-ai/integrations/overview\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenLabs Reception integrations</strong><span>Google Calendar, HubSpot, Zapier, telephony ↗</span></a><a href=\"https://elevenlabs.io/docs/reception-ai/quickstart\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenLabs Reception quickstart</strong><span>Deployment differences by location ↗</span></a><a href=\"https://elevenlabs.io/pricing/agents\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenAgents pricing</strong><span>Separate developer platform with minutes and LLM fees ↗</span></a><a href=\"https://elevenlabs.io/docs/help-center/product/eleven-agents/how-do-i-use-tools-with-eleven-agents\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>ElevenAgents tools</strong><span>Webhooks and system transfer tools ↗</span></a><a href=\"https://developers.openai.com/api/docs/pricing\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>OpenAI Realtime pricing</strong><span>GPT-Realtime-2.1 audio/text token billing ↗</span></a><a href=\"https://developers.openai.com/api/docs/guides/voice-sip\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>OpenAI telephony SIP</strong><span>Incoming call webhook, sideband and refer ↗</span></a><a href=\"https://developers.openai.com/api/docs/guides/voice-agents\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>OpenAI voice agents</strong><span>Voice agent architecture ↗</span></a><a href=\"https://www.twilio.com/en-us/voice/pricing/de\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Twilio Germany Voice pricing</strong><span>Country-specific transport example, not universal ↗</span></a><a href=\"https://www.edpb.europa.eu/sme/find-practical-info/faq_ro\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>EDPB data protection FAQ</strong><span>Information obligations around call recordings ↗</span></a></div></section>\n<section class=\"arg-section\"><p class=\"eyebrow\">EXPLORE THE SXF VOICE STACK</p><h2>Related voice technology and agent reliability guides.</h2>\n<div class=\"model-related-links\"><a href=\"/models/gpt-realtime-2-1/\"><span>REALTIME API</span><strong>GPT-Realtime-2.1: voice, API and pricing</strong><b>↗</b></a><a href=\"/guides/best-ai-text-to-speech-models/\"><span>SPEECH GENERATION</span><strong>Best text-to-speech models and benchmarks</strong><b>↗</b></a><a href=\"/guides/ai-agent-use-cases/\"><span>BUSINESS AUTOMATION</span><strong>50 AI agent use cases and ROI</strong><b>↗</b></a><a href=\"/guides/ai-agent-cost/\"><span>TOTAL COST</span><strong>AI agent cost and operational ROI</strong><b>↗</b></a><a href=\"/research/ai-agent-reliability/\"><span>RELIABILITY</span><strong>Beyond benchmarks: 12 reliability metrics</strong><b>↗</b></a><a href=\"/guides/ai-agent-security/\"><span>SECURITY</span><strong>Agent security, authorization and prompt injection</strong><b>↗</b></a></div></section>\n</section>"

